/**
 * RecordSearchService
 *
 * Dynamic, injection-safe record search used by the admin "record finder" component.
 *
 * - Object and field API names are resolved case-insensitively against describe metadata,
 *   so only real fields of the target object can end up in the query.
 * - Every filter value is bound as a SOQL bind variable instead of being concatenated into
 *   the query string, so values coming from the UI cannot inject SOQL.
 * - Record sharing is enforced (with sharing class) and object/field level security is
 *   enforced (explicit describe checks that raise SearchException, plus AccessLevel.USER_MODE).
 */
public with sharing class RecordSearchService {

    private static final Integer MIN_ROW_LIMIT = 1;
    private static final Integer MAX_ROW_LIMIT = 200;

    /** The only exception type ever thrown by this service. */
    public class SearchException extends Exception {
    }

    /**
     * Runs exactly one SOQL query:
     *   SELECT Id, <fields...> FROM <object>
     *   [WHERE <filterField> = :value AND ...]
     *   [ORDER BY <orderByField> ASC]
     *   LIMIT <maxRows>
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return runSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('The search could not be completed: ' + e.getMessage());
        }
    }

    private static List<SObject> runSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (maxRows == null || maxRows < MIN_ROW_LIMIT || maxRows > MAX_ROW_LIMIT) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROW_LIMIT + ' and ' + MAX_ROW_LIMIT + '.'
            );
        }

        Schema.DescribeSObjectResult objectDescribe = resolveObject(objectApiName);
        Map<String, Schema.DescribeFieldResult> fieldMap = fieldMapFor(objectDescribe);

        List<String> selectClauses = buildSelectClauses(objectDescribe, fieldMap, fields);

        Map<String, Object> bindMap = new Map<String, Object>();
        List<String> whereClauses = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                Schema.DescribeFieldResult filterDescribe =
                    resolveField(objectDescribe, fieldMap, filterField);
                requireReadable(filterDescribe);
                if (!filterDescribe.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be used in a filter: ' + filterDescribe.getName()
                    );
                }
                String bindName = 'bindValue' + bindIndex;
                bindMap.put(bindName, toBindValue(filterDescribe, filters.get(filterField)));
                whereClauses.add(filterDescribe.getName() + ' = :' + bindName);
                bindIndex++;
            }
        }

        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            Schema.DescribeFieldResult orderDescribe =
                resolveField(objectDescribe, fieldMap, orderByField);
            requireReadable(orderDescribe);
            if (!orderDescribe.isSortable()) {
                throw new SearchException(
                    'Field cannot be used for sorting: ' + orderDescribe.getName()
                );
            }
            orderByClause = ' ORDER BY ' + orderDescribe.getName() + ' ASC';
        }

        String query =
            'SELECT ' + String.join(selectClauses, ',') +
            ' FROM ' + objectDescribe.getName() +
            (whereClauses.isEmpty() ? '' : ' WHERE ' + String.join(whereClauses, ' AND ')) +
            orderByClause +
            ' LIMIT ' + maxRows;

        // USER_MODE enforces sharing, object permissions and field-level security.
        return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
    }

    private static Schema.DescribeSObjectResult resolveObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        // The global describe map has case-insensitive keys.
        Schema.SObjectType objectType = Schema.getGlobalDescribe().get(objectApiName.trim());
        if (objectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('The running user cannot read object: ' + objectDescribe.getName());
        }
        return objectDescribe;
    }

    private static Map<String, Schema.DescribeFieldResult> fieldMapFor(
        Schema.DescribeSObjectResult objectDescribe
    ) {
        Map<String, Schema.DescribeFieldResult> fieldMap =
            new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField fieldToken : objectDescribe.fields.getMap().values()) {
            Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
            fieldMap.put(fieldDescribe.getName().toLowerCase(), fieldDescribe);
        }
        return fieldMap;
    }

    private static Schema.DescribeFieldResult resolveField(
        Schema.DescribeSObjectResult objectDescribe,
        Map<String, Schema.DescribeFieldResult> fieldMap,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException(
                'Field does not exist on ' + objectDescribe.getName() + ': ' + fieldName
            );
        }
        Schema.DescribeFieldResult fieldDescribe = fieldMap.get(fieldName.trim().toLowerCase());
        if (fieldDescribe == null) {
            throw new SearchException(
                'Field does not exist on ' + objectDescribe.getName() + ': ' + fieldName
            );
        }
        return fieldDescribe;
    }

    private static void requireReadable(Schema.DescribeFieldResult fieldDescribe) {
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException('The running user cannot read field: ' + fieldDescribe.getName());
        }
    }

    private static List<String> buildSelectClauses(
        Schema.DescribeSObjectResult objectDescribe,
        Map<String, Schema.DescribeFieldResult> fieldMap,
        List<String> fields
    ) {
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be specified.');
        }
        List<String> selectClauses = new List<String>{ 'Id' };
        Set<String> usedFieldNames = new Set<String>{ 'id' };
        for (String fieldName : fields) {
            Schema.DescribeFieldResult fieldDescribe =
                resolveField(objectDescribe, fieldMap, fieldName);
            requireReadable(fieldDescribe);
            String canonicalName = fieldDescribe.getName();
            if (usedFieldNames.contains(canonicalName.toLowerCase())) {
                continue;
            }
            usedFieldNames.add(canonicalName.toLowerCase());
            selectClauses.add(canonicalName);
        }
        return selectClauses;
    }

    /**
     * Converts a raw UI value into the Apex type expected by the target field so that the
     * value can be bound safely. Throws SearchException when the value cannot be converted.
     */
    private static Object toBindValue(Schema.DescribeFieldResult fieldDescribe, Object rawValue) {
        if (rawValue == null) {
            return null;
        }
        String fieldName = fieldDescribe.getName();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        try {
            if (fieldType == Schema.DisplayType.DATE) {
                if (rawValue instanceof Date) {
                    return (Date) rawValue;
                }
                if (rawValue instanceof Datetime) {
                    return ((Datetime) rawValue).date();
                }
                if (rawValue instanceof String) {
                    return parseDate((String) rawValue);
                }
            } else if (fieldType == Schema.DisplayType.DATETIME) {
                if (rawValue instanceof Datetime) {
                    return (Datetime) rawValue;
                }
                if (rawValue instanceof Date) {
                    return Datetime.newInstance((Date) rawValue, Time.newInstance(0, 0, 0, 0));
                }
                if (rawValue instanceof String) {
                    return parseDateTime((String) rawValue);
                }
            } else if (fieldType == Schema.DisplayType.TIME) {
                if (rawValue instanceof Time) {
                    return (Time) rawValue;
                }
                if (rawValue instanceof String) {
                    return parseTime((String) rawValue);
                }
            } else if (fieldType == Schema.DisplayType.BOOLEAN) {
                if (rawValue instanceof Boolean) {
                    return (Boolean) rawValue;
                }
                if (rawValue instanceof String) {
                    return parseBoolean((String) rawValue);
                }
            } else if (fieldType == Schema.DisplayType.INTEGER) {
                return toDecimalValue(rawValue).intValue();
            } else if (fieldType == Schema.DisplayType.LONG) {
                return toLongValue(rawValue);
            } else if (
                fieldType == Schema.DisplayType.DOUBLE ||
                fieldType == Schema.DisplayType.CURRENCY ||
                fieldType == Schema.DisplayType.PERCENT
            ) {
                return toDecimalValue(rawValue);
            } else if (
                fieldType == Schema.DisplayType.ID ||
                fieldType == Schema.DisplayType.REFERENCE
            ) {
                return toIdValue(rawValue);
            } else {
                return String.valueOf(rawValue);
            }
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Invalid filter value for field ' + fieldName + ': ' + rawValue);
        }
        throw new SearchException('Unsupported filter value for field ' + fieldName + ': ' + rawValue);
    }

    private static Decimal toDecimalValue(Object rawValue) {
        if (rawValue instanceof Decimal) {
            return (Decimal) rawValue;
        }
        if (rawValue instanceof String) {
            return Decimal.valueOf(((String) rawValue).trim());
        }
        return Decimal.valueOf(String.valueOf(rawValue));
    }

    private static Long toLongValue(Object rawValue) {
        String plain = toDecimalValue(rawValue).toPlainString();
        Integer dotIndex = plain.indexOf('.');
        if (dotIndex != -1) {
            plain = plain.substring(0, dotIndex);
        }
        return Long.valueOf(plain);
    }

    private static Id toIdValue(Object rawValue) {
        if (rawValue instanceof Id) {
            return (Id) rawValue;
        }
        return (Id) String.valueOf(rawValue).trim();
    }

    private static Date parseDate(String rawValue) {
        String text = rawValue.trim();
        if (text.contains('T')) {
            text = text.split('T')[0];
        } else if (text.contains(' ')) {
            text = text.split(' ')[0];
        }
        return Date.valueOf(text);
    }

    private static Datetime parseDateTime(String rawValue) {
        String text = rawValue.trim().replace('T', ' ').replace('t', ' ');
        if (text.endsWith('Z') || text.endsWith('z')) {
            text = text.substring(0, text.length() - 1).trim();
        }
        Integer offsetIndex = text.lastIndexOf('+');
        if (offsetIndex > 10) {
            text = text.substring(0, offsetIndex).trim();
        }
        if (text.length() > 19) {
            text = text.substring(0, 19);
        }
        if (text.length() == 10) {
            text = text + ' 00:00:00';
        } else if (text.length() == 16) {
            text = text + ':00';
        }
        return Datetime.valueOf(text);
    }

    private static Time parseTime(String rawValue) {
        // Time.valueOf(String) does not exist in Apex, so parse manually.
        String text = rawValue.trim();
        Integer fractionIndex = text.indexOf('.');
        if (fractionIndex != -1) {
            text = text.substring(0, fractionIndex);
        }
        List<String> parts = text.split(':');
        if (parts.size() < 2 || parts.size() > 3) {
            throw new SearchException('Invalid time filter value: ' + rawValue);
        }
        Integer hours = Integer.valueOf(parts[0].trim());
        Integer minutes = Integer.valueOf(parts[1].trim());
        Integer seconds = parts.size() == 3 ? Integer.valueOf(parts[2].trim()) : 0;
        return Time.newInstance(hours, minutes, seconds, 0);
    }

    private static Boolean parseBoolean(String rawValue) {
        String text = rawValue.trim();
        if (text.equalsIgnoreCase('true')) {
            return true;
        }
        if (text.equalsIgnoreCase('false')) {
            return false;
        }
        throw new SearchException('Invalid boolean filter value: ' + rawValue);
    }
}
