        System.assertEquals('Keep won', [SELECT NextStep FROM Opportunity WHERE Id = :alreadyWonOpp.Id].NextStep,
            'An already won opportunity must not be touched.');
        System.assertEquals('Keep lost', [SELECT NextStep FROM Opportunity WHERE Id = :leavingWonOpp.Id].NextStep,
