            );
            if (i < 40) {
                o.StageName = WON;
                o.AccountId = warmForWon[i].Id;
            } else if (i < 70) {
                o.StageName = WON;
                o.AccountId = hotForWon[i - 40].Id;
            } else if (i < 100) {
                o.StageName = WON;
            } else {
