public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET_NAME = 'Credit_Review';
    private static final String CONTACTS_RELATIONSHIP_NAME = 'Contacts';

    // Default Application factory usage: queries run in user mode (WITH USER_MODE)
    // so the platform enforces the running user's object, field and sharing access.
    public AccountsSelector() {
        super(fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    // Base fields plus every field currently in the Credit_Review field set,
    // so admins can add fields without code changes.
    public override List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        for (Schema.SObjectField creditReviewField : getCreditReviewFields()) {
            if (!fields.contains(creditReviewField)) {
                fields.add(creditReviewField);
            }
        }
        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        fflib_QueryFactory accountQueryFactory = newQueryFactory();
        accountQueryFactory.setCondition('Id IN :accountIds');

        // Build the child subquery from the ContactsSelector so it uses that selector's fields
        fflib_QueryFactory contactsQueryFactory =
            accountQueryFactory.subselectQuery(CONTACTS_RELATIONSHIP_NAME);
        contactsQueryFactory.selectFields(new ContactsSelector().getSObjectFieldList());

        return (List<Account>) Database.query(accountQueryFactory.toSOQL());
    }

    private static List<Schema.SObjectField> getCreditReviewFields() {
        Schema.DescribeSObjectResult accountDescribe = Account.SObjectType.getDescribe();

        Schema.FieldSet creditReviewFieldSet =
            accountDescribe.fieldSets.getMap().get(CREDIT_REVIEW_FIELD_SET_NAME);
        if (creditReviewFieldSet == null) {
            throw new AccountsSelectorException(
                'The Account field set "' + CREDIT_REVIEW_FIELD_SET_NAME + '" is required but was not found.'
            );
        }

        Map<String, Schema.SObjectField> accountFieldsByName = accountDescribe.fields.getMap();
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>();
        for (Schema.FieldSetMember member : creditReviewFieldSet.getFields()) {
            fields.add(accountFieldsByName.get(member.getFieldPath()));
        }
        return fields;
    }

    public class AccountsSelectorException extends Exception {
    }
}
