/**
 * Keeps a donor's current employer (an existing Organization Account) in sync with NPSP.
 *
 * For every Contact the method guarantees:
 *   - a Current, primary npe5__Affiliation__c to the employer organisation,
 *   - Contact.npsp__Primary_Affiliation__c pointing at that same organisation,
 *   - a previous primary employer demoted by NPSP itself to a Former, non-primary
 *     affiliation with an end date of today (standard NPSP behaviour whenever an
 *     affiliation is marked primary),
 *   - the Contact stays on its Household Account (the account is never touched),
 *   - no duplicate affiliation when the organisation is already the primary one.
 *
 * Bulk-safe for 200 contacts: uses at most 2 SOQL queries and 2 DML statements
 * of its own (NPSP's own trigger work is on top of that).
 */
public with sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';
    private static final String ROLE_EMPLOYER = 'Employer';

    /**
     * Makes the given Organization Account the current, primary employer of each Contact.
     *
     * @param employerByContactId Contact Id => Organization Account Id.
     *                            Null or empty is a no-op; incomplete pairs are ignored.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Normalise the input: only keep complete Contact/Account pairs.
        Map<Id, Id> orgIdByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                orgIdByContactId.put(contactId, orgId);
            }
        }
        if (orgIdByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = orgIdByContactId.keySet();
        Set<Id> orgIds = new Set<Id>(orgIdByContactId.values());

        // ---- SOQL 1: the contacts themselves (also lets us read the current primary
        //      affiliation lookup so we can tell what actually has to change).
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, AccountId, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // ---- SOQL 2: affiliations that already link these contacts to these organisations,
        //      so an existing record is updated instead of duplicated.
        Map<Id, Map<Id, npe5__Affiliation__c>> affiliationByOrgByContact =
            new Map<Id, Map<Id, npe5__Affiliation__c>>();

        for (npe5__Affiliation__c affl : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c, npe5__Role__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Organization__c IN :orgIds
        ]) {
            Map<Id, npe5__Affiliation__c> byOrg = affiliationByOrgByContact.get(affl.npe5__Contact__c);
            if (byOrg == null) {
                byOrg = new Map<Id, npe5__Affiliation__c>();
                affiliationByOrgByContact.put(affl.npe5__Contact__c, byOrg);
            }
            // If several records exist for the same pair, keep the most relevant one.
            npe5__Affiliation__c existing = byOrg.get(affl.npe5__Organization__c);
            if (existing == null || rank(affl) > rank(existing)) {
                byOrg.put(affl.npe5__Organization__c, affl);
            }
        }

        List<npe5__Affiliation__c> affiliationsToUpsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();
        Date today = Date.today();

        for (Id contactId : orgIdByContactId.keySet()) {
            Contact con = contactsById.get(contactId);
            if (con == null) {
                // Stale Id supplied by the caller - nothing to synchronise for it.
                continue;
            }
            Id orgId = orgIdByContactId.get(contactId);

            Map<Id, npe5__Affiliation__c> byOrg = affiliationByOrgByContact.get(contactId);
            npe5__Affiliation__c affl = (byOrg == null) ? null : byOrg.get(orgId);

            // Already fully in sync: do not touch anything, in particular do not
            // create a second affiliation for the same organisation.
            Boolean alreadyPrimaryCurrent =
                affl != null &&
                affl.npe5__Primary__c == true &&
                affl.npe5__Status__c == STATUS_CURRENT;
            Boolean lookupAlreadyCorrect = con.npsp__Primary_Affiliation__c == orgId;

            if (alreadyPrimaryCurrent && lookupAlreadyCorrect) {
                continue;
            }

            if (affl == null) {
                affl = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId
                );
            }
            // Marking the affiliation primary is NPSP's standard mechanism: NPSP demotes any
            // previous primary affiliation to Former / non-primary / EndDate = today for us.
            affl.npe5__Primary__c = true;
            affl.npe5__Status__c = STATUS_CURRENT;
            affl.npe5__EndDate__c = null;
            if (affl.npe5__StartDate__c == null) {
                affl.npe5__StartDate__c = today;
            }
            if (String.isBlank(affl.npe5__Role__c)) {
                affl.npe5__Role__c = ROLE_EMPLOYER;
            }
            affiliationsToUpsert.add(affl);

            if (!lookupAlreadyCorrect) {
                // Only the affiliation lookup is written; the Household Account is untouched.
                contactsToUpdate.add(new Contact(
                    Id = contactId,
                    npsp__Primary_Affiliation__c = orgId
                ));
            }
        }

        // ---- DML 1: a single upsert covers both new and existing affiliation records.
        if (!affiliationsToUpsert.isEmpty()) {
            upsert affiliationsToUpsert;
        }

        // ---- DML 2: keep the contact's primary affiliation lookup pointing at the organisation.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    /**
     * Higher score = better candidate to reuse when duplicate affiliations exist for the
     * same contact/organisation pair.
     */
    private static Integer rank(npe5__Affiliation__c affl) {
        Integer score = 0;
        if (affl.npe5__Primary__c == true) {
            score += 2;
        }
        if (affl.npe5__Status__c == STATUS_CURRENT) {
            score += 1;
        }
        return score;
    }
}
