/**
 * Service used by the donation form integration to create Enhanced Recurring
 * Donations (NPSP RD2) for monthly giving sign-ups.
 *
 * Bulk-safe: validation happens before any DML and all gifts are inserted with a
 * single insert statement. NPSP generates the installment opportunities from the
 * recurring donation schedules; this service never creates Opportunities itself.
 */
public with sharing class RecurringGiftService {

    /** Thrown when one or more requests fail validation. */
    public class RecurringGiftException extends Exception {}

    /** Payload sent by the donation form. */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;   // 1-31, where 31 means last day of month
        public Date startDate;
        public Integer installments; // null or 0 = no end date
        public String paymentMethod; // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String STATUS_ACTIVE = 'Active';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String SCHEDULE_TYPE_OPEN = 'Open';
    private static final String SCHEDULE_TYPE_MULTIPLY_BY = 'Multiply By';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_CLOSED = 'Closed';
    private static final String DAY_OF_MONTH_FIELD = 'npsp__Day_of_Month__c';
    private static final Integer LAST_DAY_OF_MONTH = 31;

    private static Schema.DisplayType dayOfMonthFieldType;

    /**
     * Creates one monthly Enhanced Recurring Donation per request and returns the
     * new record Ids in request order.
     *
     * @param requests the sign-ups from the donation form
     * @return the created recurring donation Ids, in request order
     * @throws RecurringGiftException when any request is invalid; no DML is done
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> giftIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return giftIds;
        }

        // Validate everything first so nothing is partially created.
        validate(requests);

        List<npe03__Recurring_Donation__c> gifts = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            gifts.add(buildGift(request));
        }

        insert gifts;

        for (npe03__Recurring_Donation__c gift : gifts) {
            giftIds.add(gift.Id);
        }
        return giftIds;
    }

    private static void validate(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];

            if (request == null) {
                throw new RecurringGiftException('Request ' + i + ' is null.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Request ' + i + ': contactId is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException(
                    'Request ' + i + ': amount must be greater than zero.'
                );
            }
            if (request.dayOfMonth == null
                    || request.dayOfMonth < 1
                    || request.dayOfMonth > LAST_DAY_OF_MONTH) {
                throw new RecurringGiftException(
                    'Request ' + i + ': dayOfMonth must be between 1 and 31.'
                );
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Request ' + i + ': startDate is required.');
            }
        }
    }

    private static npe03__Recurring_Donation__c buildGift(GiftRequest request) {
        Boolean openEnded = request.installments == null || request.installments == 0;
        Boolean useLastDayOfMonth = request.dayOfMonth == LAST_DAY_OF_MONTH;

        npe03__Recurring_Donation__c gift = new npe03__Recurring_Donation__c(
            npe03__Contact__c = request.contactId,
            npe03__Amount__c = request.amount,
            npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c = 1,
            npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth,
            npsp__StartDate__c = request.startDate,
            npsp__Status__c = STATUS_ACTIVE,
            npsp__PaymentMethod__c = request.paymentMethod
        );

        gift.put(DAY_OF_MONTH_FIELD, dayOfMonthValue(request));

        if (openEnded) {
            // No end date: NPSP schedules installments until the gift is closed.
            gift.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
            gift.npe03__Schedule_Type__c = SCHEDULE_TYPE_OPEN;
            gift.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
            gift.npe03__Installments__c = null;
            gift.npsp__EndDate__c = null;
        } else {
            gift.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            gift.npe03__Schedule_Type__c = SCHEDULE_TYPE_MULTIPLY_BY;
            gift.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_CLOSED;
            gift.npe03__Installments__c = request.installments;
            gift.npsp__EndDate__c = plannedEndDate(request);
        }

        return gift;
    }

    /**
     * Returns the day of month in the type expected by the field (picklist in some
     * orgs, number in others), so the class compiles either way.
     */
    private static Object dayOfMonthValue(GiftRequest request) {
        Schema.DisplayType fieldType = dayOfMonthFieldType();
        if (fieldType == Schema.DisplayType.Picklist
                || fieldType == Schema.DisplayType.String
                || fieldType == Schema.DisplayType.TextArea) {
            return String.valueOf(request.dayOfMonth);
        }
        return request.dayOfMonth;
    }

    private static Schema.DisplayType dayOfMonthFieldType() {
        if (dayOfMonthFieldType == null) {
            dayOfMonthFieldType = npe03__Recurring_Donation__c.SObjectType.getDescribe()
                .fields.getMap()
                .get(DAY_OF_MONTH_FIELD)
                .getDescribe()
                .getType();
        }
        return dayOfMonthFieldType;
    }

    /** First scheduled installment date: the requested day in the start month. */
    private static Date firstInstallmentDate(GiftRequest request) {
        Integer daysInStartMonth = Date.daysInMonth(
            request.startDate.year(),
            request.startDate.month()
        );
        Integer day = request.dayOfMonth;
        if (request.dayOfMonth == LAST_DAY_OF_MONTH || day > daysInStartMonth) {
            day = daysInStartMonth;
        }
        return Date.newInstance(request.startDate.year(), request.startDate.month(), day);
    }

    /** End date for a fixed-length gift: last installment date. */
    private static Date plannedEndDate(GiftRequest request) {
        return firstInstallmentDate(request).addMonths(request.installments - 1);
    }
}
